const items = $input.all();

const now = new Date();
const formattedDate =
  `${now.getMonth() + 1}/${now.getDate()}/${now.getFullYear()}`;

const results = [];
// Trusted tenant context injected by crm-lead-intake.
// Never take workspace_id from the AI classifier output.
const workspaceId = $('Webhook').first().json.body?.workspace_id || null;

for (const item of items) {
  let raw = item.json.output;

  if (!raw) continue;

  raw = raw.replace(/```json|```/g, '').trim();

  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    console.error('JSON parse failed:', error);
    continue;
  }

  const leads = Array.isArray(parsed) ? parsed : [parsed];

  for (const lead of leads) {
    const rawCurrency = String(
      lead.currency_code || 'USD'
    ).trim().toUpperCase();

    const currencyCode =
      /^[A-Z]{3}$/.test(rawCurrency)
        ? rawCurrency
        : 'USD';

    results.push({
      json: {
        name: lead.name || '',
        email: lead.email || '',
        message: lead.message || lead.notes || '',
        budget: lead.budget ?? '',
        currency_code: currencyCode,
        category: lead.category || '',
        intent: lead.intent || '',
        summary: lead.summary || '',
        date: formattedDate,
        submission_type: lead.submission_type,
        workspace_id: workspaceId
      }
    });
  }
}

// If nothing could be parsed into a usable lead, still emit exactly one item
// so downstream nodes actually run (n8n never invokes a node connected to an
// empty output array) and the caller gets a real error instead of a silently
// dropped request.
if (results.length === 0) {
  return [{
    json: {
      __intake_ok: false,
      __intake_stage: 'classification',
      __intake_error: 'The AI classifier did not return a usable result for this submission, so nothing was saved.',
    },
  }];
}

return results.map((item) => ({
  json: { ...item.json, __intake_ok: true },
}));

const items = $input.all().map((item) => item.json);

return [{
  json: {
    ok: true,
    submission_type: items[0]?.source ?? null,
    saved_count: items.length,
    leads: items.map((lead) => ({
      id: lead.id ?? null,
      public_id: lead.public_id ?? null,
      name: lead.name ?? null,
      email: lead.email ?? null,
      category: lead.category ?? null,
      intent: lead.intent ?? null,
      routing_status: lead.routing_status ?? null,
      currency_code: lead.currency_code ?? null,
      budget: lead.budget ?? null,
    })),
  },
}];

const items = $input.all();
const first = items[0]?.json || {};

let stage = 'unknown';
let message = 'The lead could not be processed.';

if (typeof first.__intake_ok !== 'undefined') {
  stage = first.__intake_stage || 'classification';
  message = first.__intake_error || message;
} else {
  stage = 'persistence';
  message = (first.error && (first.error.message || first.error.description))
    || first.message
    || 'The lead could not be saved to the CRM database.';
}

return [{
  json: { ok: false, stage, error: message },
}];
